Here's a complete, self-contained Account Settings screen for React Native (TypeScript), using only core RN components so it runs on both iOS and Android without extra dependencies.

```tsx
// AccountSettingsScreen.tsx
import React, { useState, useCallback } from 'react';
import {
  View,
  Text,
  Image,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  Alert,
  ActivityIndicator,
  Platform,
  SafeAreaView,
} from 'react-native';

// ---------- Types ----------

interface UserProfile {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface SettingsRowConfig {
  key: string;
  label: string;
  value?: string;
  onPress: () => void;
}

interface AccountSettingsScreenProps {
  user: UserProfile;
  onEditProfile: () => void;
  onNavigate: (routeKey: string) => void;
  onDeleteAccount: () => Promise<void>;
  onLogout: () => void;
}

// ---------- Reusable row components ----------

function ProfileRow({
  user,
  onPress,
}: {
  user: UserProfile;
  onPress: () => void;
}) {
  const initials = user.name
    .split(' ')
    .map((part) => part[0])
    .join('')
    .slice(0, 2)
    .toUpperCase();

  return (
    <TouchableOpacity
      style={styles.profileRow}
      onPress={onPress}
      activeOpacity={0.6}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile for ${user.name}`}
    >
      {user.avatarUrl ? (
        <Image source={{ uri: user.avatarUrl }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback]}>
          <Text style={styles.avatarInitials}>{initials}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={styles.profileName} numberOfLines={1}>
          {user.name}
        </Text>
        <Text style={styles.profileEmail} numberOfLines={1}>
          {user.email}
        </Text>
      </View>
      <Text style={styles.chevron}>{'>'}</Text>
    </TouchableOpacity>
  );
}

function SettingsRow({
  label,
  value,
  onPress,
  destructive = false,
  disabled = false,
  loading = false,
  isLast = false,
}: {
  label: string;
  value?: string;
  onPress: () => void;
  destructive?: boolean;
  disabled?: boolean;
  loading?: boolean;
  isLast?: boolean;
}) {
  return (
    <TouchableOpacity
      style={[styles.row, isLast && styles.rowLast]}
      onPress={onPress}
      disabled={disabled || loading}
      activeOpacity={0.6}
      accessibilityRole="button"
      accessibilityState={{ disabled: disabled || loading }}
    >
      <Text
        style={[styles.rowLabel, destructive && styles.rowLabelDestructive]}
      >
        {label}
      </Text>
      <View style={styles.rowRight}>
        {loading ? (
          <ActivityIndicator size="small" color={destructive ? '#D92D20' : '#8A8A8E'} />
        ) : (
          <>
            {value ? <Text style={styles.rowValue}>{value}</Text> : null}
            {!destructive && <Text style={styles.chevron}>{'>'}</Text>}
          </>
        )}
      </View>
    </TouchableOpacity>
  );
}

function Section({
  title,
  children,
}: {
  title?: string;
  children: React.ReactNode;
}) {
  return (
    <View style={styles.section}>
      {title ? <Text style={styles.sectionTitle}>{title}</Text> : null}
      <View style={styles.sectionCard}>{children}</View>
    </View>
  );
}

// ---------- Main screen ----------

export default function AccountSettingsScreen({
  user,
  onEditProfile,
  onNavigate,
  onDeleteAccount,
  onLogout,
}: AccountSettingsScreenProps) {
  const [isDeleting, setIsDeleting] = useState(false);

  const preferenceRows: SettingsRowConfig[] = [
    {
      key: 'notifications',
      label: 'Notifications',
      onPress: () => onNavigate('notifications'),
    },
    {
      key: 'appearance',
      label: 'Appearance',
      value: 'System',
      onPress: () => onNavigate('appearance'),
    },
    {
      key: 'language',
      label: 'Language',
      value: 'English',
      onPress: () => onNavigate('language'),
    },
  ];

  const securityRows: SettingsRowConfig[] = [
    {
      key: 'password',
      label: 'Change password',
      onPress: () => onNavigate('change-password'),
    },
    {
      key: '2fa',
      label: 'Two-factor authentication',
      value: 'Off',
      onPress: () => onNavigate('two-factor'),
    },
  ];

  const supportRows: SettingsRowConfig[] = [
    {
      key: 'help',
      label: 'Help center',
      onPress: () => onNavigate('help-center'),
    },
    {
      key: 'contact',
      label: 'Contact us',
      onPress: () => onNavigate('contact-us'),
    },
  ];

  const runDeleteAccount = useCallback(async () => {
    try {
      setIsDeleting(true);
      await onDeleteAccount();
    } catch (err) {
      Alert.alert(
        'Something went wrong',
        'We couldn\u2019t delete your account. Please try again.'
      );
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount]);

  const confirmDeleteAccount = useCallback(() => {
    if (isDeleting) return;

    Alert.alert(
      'Delete account',
      'This permanently deletes your account and all associated data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: runDeleteAccount,
        },
      ],
      { cancelable: true }
    );
  }, [isDeleting, runDeleteAccount]);

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        <Text style={styles.screenTitle}>Account</Text>

        <Section>
          <ProfileRow user={user} onPress={onEditProfile} />
        </Section>

        <Section title="Preferences">
          {preferenceRows.map((row, index) => (
            <SettingsRow
              key={row.key}
              label={row.label}
              value={row.value}
              onPress={row.onPress}
              isLast={index === preferenceRows.length - 1}
            />
          ))}
        </Section>

        <Section title="Security">
          {securityRows.map((row, index) => (
            <SettingsRow
              key={row.key}
              label={row.label}
              value={row.value}
              onPress={row.onPress}
              isLast={index === securityRows.length - 1}
            />
          ))}
        </Section>

        <Section title="Support">
          {supportRows.map((row, index) => (
            <SettingsRow
              key={row.key}
              label={row.label}
              value={row.value}
              onPress={row.onPress}
              isLast={index === supportRows.length - 1}
            />
          ))}
        </Section>

        <Section>
          <SettingsRow label="Log out" onPress={onLogout} isLast />
        </Section>

        <Section title="Danger zone">
          <SettingsRow
            label={isDeleting ? 'Deleting account\u2026' : 'Delete account'}
            onPress={confirmDeleteAccount}
            destructive
            disabled={isDeleting}
            loading={isDeleting}
            isLast
          />
        </Section>
      </ScrollView>
    </SafeAreaView>
  );
}

// ---------- Styles ----------

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#F2F2F7',
  },
  scrollContent: {
    paddingHorizontal: 16,
    paddingBottom: 40,
  },
  screenTitle: {
    fontSize: 28,
    fontWeight: '700',
    color: '#1C1C1E',
    marginTop: Platform.select({ ios: 12, android: 20 }),
    marginBottom: 16,
  },
  section: {
    marginBottom: 24,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    color: '#6D6D72',
    textTransform: 'uppercase',
    letterSpacing: 0.4,
    marginBottom: 6,
    marginLeft: 4,
  },
  sectionCard: {
    backgroundColor: '#FFFFFF',
    borderRadius: 12,
    overflow: 'hidden',
    ...Platform.select({
      ios: {
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 1 },
        shadowOpacity: 0.05,
        shadowRadius: 2,
      },
      android: {
        elevation: 1,
      },
    }),
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 14,
    paddingHorizontal: 16,
  },
  avatar: {
    width: 52,
    height: 52,
    borderRadius: 26,
    marginRight: 14,
  },
  avatarFallback: {
    backgroundColor: '#D6D6DA',
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    fontSize: 18,
    fontWeight: '600',
    color: '#4A4A4C',
  },
  profileText: {
    flex: 1,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    color: '#1C1C1E',
  },
  profileEmail: {
    fontSize: 14,
    color: '#6D6D72',
    marginTop: 2,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 14,
    paddingHorizontal: 16,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: '#E5E5EA',
  },
  rowLast: {
    borderBottomWidth: 0,
  },
  rowLabel: {
    fontSize: 16,
    color: '#1C1C1E',
  },
  rowLabelDestructive: {
    color: '#D92D20',
  },
  rowRight: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  rowValue: {
    fontSize: 15,
    color: '#8A8A8E',
    marginRight: 6,
  },
  chevron: {
    fontSize: 15,
    color: '#C7C7CC',
    marginLeft: 6,
  },
});
